  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.klairs.com/pages/creator-program', 'official_site', 'compensation', 'Official Creator Program page: ''Earn a 10% base commission on approved klairs.com sales, with 15% commission for Blue Line products''; 30-day attribution after click; ''Payouts are handled through PayPal on a monthly schedule.'' No cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.klairs.com/pages/creator-program', 'official_site', 'ugc_collab', 'Program explicitly welcomes nano and micro creators (''Audience size is not the main filter, and micro creators are welcome''), applications are reviewed manually usually within 7 days, and approved creators get seeding opportunities, a Content Kit, and an Earn-a-kit $30 reimbursement. Application runs via Shopify Collabs.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/klairs', 'listing', 'ugc_collab', 'Beacons Universe: Klairs is a skincare & beauty brand based in Seoul, South Korea, ''with posts from 366 creators (all time)'' — a real creator footprint, but far below saturated leaders (e.g., OSEA at 4,050), supporting a ''medium'' saturation label.', 'publicly_reported', now());
