  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.neededpartnerhub.com/', 'official_site', 'affiliate', 'Official Needed Partner Hub fetched: ''ShopMy — 16% commission on every sale. Impact — Up to $75 per new customer you influence. TikTok Shop — Up to 20% commission on every sale.'' Also: ''Top partners are making thousands monthly.'' That earnings line is NOT an explicit no-cap/unlimited statement, and no other cap wording appears — commission_cap is unknown. Ambassador contact on the page: ambassadors@thisisneeded.com. Rate field = 20, the highest published % (TikTok Shop).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.neededpartnerhub.com/', 'official_site', 'ugc_collab', 'Partner Hub: ''Join our UGC Program and create content for Needed to launch in paid ads. We''ll pay you $100 for every selected piece.'' Perks also include regular gifting to creators, increased-commission opportunities, content boosting, and top-partner paid campaigns, whitelisting, event invites and features.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thisisneeded.com/pages/needed-academy', 'official_site', 'affiliate', 'Official Needed Academy page: completing the free program and a short quiz lets you ''partner with us, which unlocks perks including commission, free products, discounts to share with your community, exclusive sneak peeks.'' It also states partners ''join our community of thousands of partners for life'' — evidence of a large existing partner base, recorded as high creator saturation.', 'verified', now());
