  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 8, 6, 8, 4, '{"niche_fit": "Gut-health supplements, strong wellness/food fit", "ugc_evidence": "Official ambassador campaigns/feature promise plus 25 Beacons creators", "compensation": "Cash 10% only after Tier 5; base pay is capped product-point tiers, no uncapped statement", "contact_access": "Ambassador application page + phone, no published email", "opportunity_availability": "Open ambassador page on own site", "credibility": "Official program page and Beacons brand page verified"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Just Thrive', 'https://justthrivehealth.com/', 'Just Thrive makes spore-based probiotic and gut-health supplements; its official affiliate toolkit says its probiotic is the only probiotic to arrive 100% alive to the digestive tract, where it creates antioxidants and supports a balanced microbiome. The brand runs an affiliate program through Refersion with dedicated affiliate contacts and swipe copy, photos and social examples for partners.', 'United States', 'published') returning id into bid;
