  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://justthrivehealth.com/pages/affiliate-tool-kit', 'official_site', 'affiliate', 'Official Affiliate Tool Kit fetched in full: ''Welcome to the Just Thrive Affiliate Program'', ''Log Into Refersion'', images ''also available in your affiliate dashboard in Refersion under Creatives'', hashtag #justthrivepartner, and ''You have 2 dedicated contacts! Please email Beth@justthrivehealth.com and Sara@justthrivehealth.com.'' No commission % and no cap/uncapped wording on the official page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/just-thrive/', 'listing', 'affiliate', 'Lasso listing reports 5% per sale, 45-day cookie. Another listing (Strackr) reports 10% and 6-month cookie, so published listing rates conflict; official rate is unpublished, hence commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/just-thrive', 'listing', 'ugc_collab', 'Beacons Universe: ''Just Thrive is a health & wellness brand based in Park Ridge, United States, with posts from 60 creators (all time)'' ; ''2 posted in the last 30 days''; ''32 public posts mentioned Just Thrive in the last 12 months''; 17 sponsored posts in last 12 months. Small creator count is evidence for low saturation.', 'publicly_reported', now());
