  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 4, 12, 5, 4, '{"niche_fit": "Gut health / probiotic is a core health and wellness fit.", "ugc_evidence": "Official toolkit with social post examples plus Beacons sponsored posts, but only 60 creators all-time.", "compensation": "No rate on official page and listings conflict at 5% vs 10%; no uncapped statement, so low.", "contact_access": "Two named dedicated affiliate emails published on the official toolkit page.", "opportunity_availability": "Program exists via Refersion, but no public join/application form was found, only a toolkit/login page.", "credibility": "Official toolkit, contacts and network verified; rate credibility weakened by conflicting listings."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('WOOPF', 'https://woopf.com/', 'Vet-designed dog gear brand founded by emergency veterinarian Dr Duncan Houston (BVSc, University of Sydney), operated by Australian Premium Animal Products Ltd, Hong Kong. Its range covers front-clip harnesses, leads and collars, waterproof collars, chew toys, snuffle/lick enrichment, memory-foam beds, a Smart ID Tag and a GPS tracker. Its Ambassador Programme is creator-first: creators on Instagram, TikTok or YouTube of any size, plus trainers, groomers, walkers, clubs and rescues.', 'Hong Kong', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'hello@woopf.com', 'https://woopf.com/pages/contact', 'https://woopf.com/policies/terms-of-service', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://woopf.com/pages/ambassador-hub', 'https://woopf.com/pages/ambassador-hub', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: low (see evidence). Rate as reported by https://woopf.com/pages/ambassador-hub.', 'https://woopf.com/pages/ambassador-hub', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'WOOPF Ambassador Programme — 10% commission, no monthly cap', 'https://woopf.com/pages/ambassador-hub', 'https://woopf.com/pages/ambassador-hub', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://woopf.com/pages/ambassador-hub', 'official_site', 'affiliate', 'Official Ambassador Programme page: 10% commission on every sale through a personal code/link, tracked in a Social Snowball dashboard, a personal discount code for the audience, manual approval, and disclosure required on every post.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://woopf.com/pages/ambassador-hub', 'official_site', 'affiliate', 'Explicit uncapped wording in two places on the official page: ''10% commission — On every sale through your code or link, with no monthly cap'' and the FAQ: ''10% of every sale made through your personal code or link, with no monthly cap... paid out on the first business day of each month.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://woopf.com/pages/ambassador-hub', 'official_site', 'ugc_collab', 'The program actively recruits small/new creators: ''Creators with a dog — Instagram, TikTok or YouTube, any size''; FAQ: ''I have a small account. Is it worth applying? A small account whose followers actually own dogs and trust you is exactly who this is for. We approve on the dog, the content and the audience, not the follower count.'' Applications are read by a person in a founder-led review.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://woopf.com/policies/terms-of-service', 'official_site', 'contact', 'Terms state woopf.com is operated by Australian Premium Animal Products Ltd, Causeway Bay, Hong Kong, and publish ''Questions: hello@woopf.com'' with the contact form at woopf.com/pages/contact.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://woopf.com/', 'official_site', 'ugc_collab', 'Homepage: ''100% veterinarian owned · Founded by Dr Duncan Houston, BVSc'' and a ''SEEN ON SOCIAL • SHOP THE CLIP'' section of real dogs in real homes filmed by owners and by Dr Duncan himself.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 18, 13, 10, 5, '{"compensation": "Published 10% on every sale with an explicit no-monthly-cap statement in both the body copy and the FAQ; payout monthly via Social Snowball.", "contact_access": "Published general email hello@woopf.com in the Terms plus a contact form and a public ambassador application page.", "credibility": "Vet-owned and founder-led, with full Terms/Privacy naming the legal operator and its Hong Kong address.", "niche_fit": "Pure pet gear \u2014 harnesses, toys, beds, ID/GPS \u2014 a direct fit for pet creators.", "opportunity_availability": "Live application via Social Snowball from the ambassador hub; any-size creators and non-social professionals are eligible.", "ugc_evidence": "The homepage is built around owner-filmed ''Shop the Clip'' social video, and the ambassador programme requires creators to use the gear on their own dog and post with their code."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Raised Right', 'https://www.raisedrightpets.com/', 'Family-owned human-grade pet food company based in Rye, New York, making ''home cooked style'' whole-food, limited-ingredient, low-carb recipes for dogs and cats formulated with veterinarian Dr. Karen Becker, with every ingredient traceable and each batch lab-tested. Its affiliate program runs on ShareASale at a published 10% per sale.', 'United States', 'published') returning id into bid;
