  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://getlasso.co/affiliate/raised-right-pets/.', 'https://www.shareasale.com/shareasale.cfm?merchantID=86163', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Raised Right Pets Affiliate Program — 10% per sale via ShareASale', 'https://www.shareasale.com/shareasale.cfm?merchantID=86163', 'https://www.raisedrightpets.com/wp-content/uploads/2019/03/Raised-Right-Veterinarian-Program-Sign-Up-Guidelines.pdf', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/raised-right-pets/', 'listing', 'affiliate', 'Lasso listing: ''Commission Rate: 10% Per Sale, Cookie Duration: 15 Days'', program category Pet, with the join link going to ShareASale; the page FAQ repeats that the Raised Right Pets affiliate commission rate is 10% per sale.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.raisedrightpets.com/wp-content/uploads/2019/03/Raised-Right-Veterinarian-Program-Sign-Up-Guidelines.pdf', 'official_site', 'affiliate', 'The brand''s own sign-up guide, hosted on raisedrightpets.com, directs applicants to ShareASale merchant ID 86163 to join the program, with commissions funded by Raised Right via ShareASale escrow.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/raised-right', 'listing', 'ugc_collab', 'Beacons Universe (updated Oct 18, 2026): posts from 16 creators all time, 55 mentions all time, 5 public posts mentioning Raised Right in the last 12 months, and no creator posted about it in the 30 days to November 20, 2026 — clear low-saturation evidence. Lists 1-50 employees, based in Rye, New York.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.raisedrightpets.com/faq/', 'official_site', 'contact', 'Official FAQ/footer publishes info@raisedrightpets.com and phone 1-844-777-3871, delivery to all 48 contiguous US states, and food gently cooked in a USDA-inspected human-grade facility.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 14, 13, 9, 5, '{"compensation": "Published 10% per sale on ShareASale with a 15-day cookie; no cap statement was found, so the cap is honestly unknown.", "contact_access": "Published info@raisedrightpets.com and phone on the official site and FAQ.", "credibility": "Family-owned, HQ and officers documented by PetfoodIndustry, USDA-inspected facility claim on the official FAQ.", "niche_fit": "Fresh, human-grade dog and cat food from a family-owned brand \u2014 squarely in the pets brief.", "opportunity_availability": "Open ShareASale join flow documented in the brand''s own sign-up guide.", "ugc_evidence": "Beacons shows real creator posts (Instagram reels/posts by named creators), but very sparse \u2014 which is the opportunity."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The 2Hr Aquarist', 'https://www.2hraquarist.com/', 'Singapore planted-aquarium brand (2Hr Aquarist Pte. Ltd.) founded by aquascaper Dennis Wong, selling APT fertilisers and planted-tank products built around its ''2Hr Way'' methodology. It runs an Ambassador Program plus a Super Affiliate Program open to non-ambassadors, with link-based tracking via BixGrow, and its online store serves the US, Canada, Europe, Australia and selected parts of Asia.', 'Singapore', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_socials (brand_id, platform, handle, url) values (bid, 'youtube', 'UCaG3z-5Jwd9o_mHiMBrWhaQ', 'https://www.youtube.com/channel/UCaG3z-5Jwd9o_mHiMBrWhaQ');
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'info@2hraquarist.com', 'https://www.2hraquarist.com/policies/privacy-policy', 'https://www.2hraquarist.com/policies/privacy-policy', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'BixGrow', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.2hraquarist.com/en-fr/pages/partner-us.', 'https://www.2hraquarist.com/en-fr/pages/partner-us', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The 2Hr Aquarist Super Affiliate Program — 15% to 20% commission', 'https://www.2hraquarist.com/en-fr/pages/partner-us', 'https://www.2hraquarist.com/en-fr/pages/partner-us', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.2hraquarist.com/en-fr/pages/partner-us', 'official_site', 'affiliate', 'Official Partner Us page — Super Affiliate Program: ''While Amazon and other platforms typically pay 3-4% commissions for similar products, we give a cool 15% to 20%.'' The affiliate section adds that the program is open to interested folks beyond brand ambassadors, affiliates enjoy up to 20% commission and users get up to 12% discount; payouts monthly via PayPal with a $50 threshold.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.2hraquarist.com/en-fr/pages/partner-us', 'official_site', 'ugc_collab', 'Ambassador perks on the same page: a US$100–$250 gift card to start, a direct line to HQ and the horticulturist team, and priority access; the page notes most affiliates earn $20–$100+ per month. No creator-count source was fetched, so saturation is unknown, not low.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.2hraquarist.com/policies/privacy-policy', 'official_site', 'contact', 'Privacy Policy publishes info@2hraquarist.com and the registered address: 2Hr Aquarist Pte. Ltd., 22 Sin Ming Lane, Midview City, #06-76, Singapore 573969; the Industry Partnership page confirms HQ in Singapore.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 17, 12, 9, 5, '{"compensation": "The highest published rate in this group: 15\u201320% (up to 20%) on the official page, monthly PayPal; no cap statement found, so the cap is unknown.", "contact_access": "Published info@2hraquarist.com in the official Privacy Policy.", "credibility": "Registered Pte. Ltd. with a full Singapore address, and HQ, distributor and dealer programs documented on the official site.", "niche_fit": "Aquatics is an explicit pets sub-category, and the planted-tank niche is underserved next to dog and cat food.", "opportunity_availability": "The affiliate program is explicitly open beyond ambassadors, with a live dashboard link on the partner page.", "ugc_evidence": "The program is built for hobbyist creators sharing build threads, videos and group posts, plus a formal Ambassador tier."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('X-Sense', 'https://www.x-sense.com', 'Smart home-safety brand founded in 2013 making smoke alarms, carbon monoxide and combination alarms, heat alarms, water-leak sensors and environmental sensors, including interconnected and Wi-Fi smart versions. Its official affiliate page targets website owners, bloggers and online marketers who share banners and text links on social media.', 'United States', 'published') returning id into bid;
