  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'X-Sense Affiliate Program — 9%-16% commission, no earning limit', 'https://www.x-sense.com/pages/affiliate', 'https://www.x-sense.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.x-sense.com/pages/affiliate', 'official_site', 'affiliate', 'Official affiliate page: 9%-16% commission (earn up to 16% per successful referral), 30-day cookie, monthly payouts and ''unlimited earning potential''. Its FAQ answers ''How much can you earn?'' with: ''There is no earning limit. The more customers you refer, the more you earn!'' — the explicit wording that qualifies the cap as uncapped. Paid by the 20th of each month, free to join.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://lifestyle.middletownlifemagazine.com/story/839689/safety-measures-for-protecting-your-home-from-fire-and-carbon-monoxide/', 'article', 'contact', 'Press release: founded in 2013, safeguarded more than 15 million households, range of smoke alarms, CO detectors and environmental sensors; media contact X-SENSE ELECTRONICS LLC, partners@x-sense.com, Delaware, website x-sense.com.', 'verified', now());
