  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 18, 12, 9, 4, '{"compensation": "Published 9%-16% range with monthly payouts, and the FAQ explicitly says there is no earning limit / unlimited earning potential.", "contact_access": "Published partners@x-sense.com partnerships email plus a public affiliate page; no named affiliate manager.", "credibility": "Founded 2013 with 15M households claimed in a press release; the network name is not stated on the official page.", "niche_fit": "Smart home safety \u2014 connected alarms and sensors \u2014 is a strong home-tech fit.", "opportunity_availability": "Live official affiliate page with a Join Now / register route.", "ugc_evidence": "The affiliate page invites bloggers and marketers to share on social media, but no product-seeding UGC/review flow was found on a fetched page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vitruvi', 'https://vitruvi.com', 'Vancouver, Canada-based natural home scenting and air-care brand, founded in 2014, offering diffusers and humidifiers that use essential oils, positioned in design-centric home goods. Its official ''Home Team'' page invites content creators who share its passion for beautiful, natural air care to join as affiliates.', 'Canada', 'published') returning id into bid;
