  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 8, 15, 9, 5, '{"compensation": "Commission on every sale is promised but no percentage is published on any fetched page, so the rate is null and compensation scores low.", "contact_access": "Dedicated published partnerships, press and general emails plus a direct creator application route \u2014 top band.", "credibility": "Established 2014 Vancouver brand with an official program page and third-party company profiles.", "niche_fit": "Core home fragrance and air-care brand, squarely in the home brief.", "opportunity_availability": "Live JOIN NOW / APPLY NOW route via Shopify Collabs on the official site.", "ugc_evidence": "Official creator program with $200k+ commissions claimed, gifting and social spotlight; Beacons tracks 102 creators and one sponsored post in the last 12 months."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GL.iNet', 'https://www.gl-inet.com', 'GL.iNet makes OpenWrt-based networking gear, best known for compact travel routers, plus home routers, IoT gateways and remote KVM devices with OpenVPN and WireGuard pre-installed. Founded in 2010 and headquartered in Hong Kong (GL Technologies (Hong Kong) Limited), it runs an Awin affiliate program and a separate influencer program offering product samples and early access.', 'Hong Kong', 'published') returning id into bid;
