  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/80509', 'listing', 'affiliate', 'Awin merchant profile for GL Technologies (Hong Kong) Limited: ''Welcome to The GL.iNet Affiliate Program! Here you can earn up to 10% commission on each affiliate sale by promoting the best-selling travel routers.'' Join by registering on Awin; questions to marketing@gl-inet.com, published on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gl-inet.com/en-us/pages/influencers', 'official_site', 'ugc_collab', 'Official Influencer Program page: seeks influencers in technology, cybersecurity, networking, travel, remote work, IoT, VPN and tech gadgets; benefits are product samples, early access to review new products and exclusive updates, with an application form on the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.gl-inet.com/en-us/pages/gl-blackfridaycreatorrewards_261101', 'official_site', 'ugc_collab', 'Official Black Friday Creator Rewards page: earn up to US$800 per creator ($100 per 20K qualifying views, $800 max at 160K+) for one video on YouTube, Instagram Reels or TikTok published Nov 1–Dec 1, 2026 (UTC+8); creators 18+ with no minimum follower count required.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 13, 14, 10, 5, '{"compensation": "The Awin listing states up to 10% commission (exact tier not published); the separate creator campaign pays up to $800 per creator by views.", "contact_access": "Published marketing@gl-inet.com on the Awin program page, plus an influencer application form on the official site.", "credibility": "Commission and contact come from the program''s Awin merchant profile; campaign terms are fully detailed on the brand''s own page.", "niche_fit": "Travel routers and networking gadgets are core consumer tech for travel, remote-work and VPN creators.", "opportunity_availability": "A dated, live opportunity: Black Friday Creator Rewards, Nov 1\u2013Dec 1, 2026, explicitly with no minimum follower count.", "ugc_evidence": "A standing influencer program (samples, early review access) plus a paid, view-based creator rewards campaign on the official site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Paperlike', 'https://paperlike.com', 'Paperlike makes the paper-feel iPad screen protector using its Nanodots surface technology, for drawing and writing with Apple Pencil in apps such as Procreate, Goodnotes and Notability, plus related iPad accessories; it is designed in Germany and manufactured in Switzerland, with the company in Hamburg, founded in 2017. It runs both a creator community (free product, pool for future paid campaigns) and a separate affiliate program.', 'Germany', 'published') returning id into bid;
