  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://paperlike.com/pages/affiliates-creators', 'official_site', 'affiliate', 'Official affiliate/creator page: ''Apply to our affiliate program to earn 10% commission on every purchase made through your affiliate link''; the FAQ confirms 10% on every sale within 30 days. Creator community members receive a free Screen Protector and join the pool for future paid campaigns; the brand seeks creators with over 5K followers.', 'verified', now());
