  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 14, 12, 9, 5, '{"compensation": "Published 10% commission on every sale within 30 days; paid campaigns are separate and unpriced publicly.", "contact_access": "Two live public application routes (creator community and affiliate); no published partnerships email was found.", "credibility": "All terms taken from the brand''s own affiliates/creators page and its live application portal.", "niche_fit": "Single-category iPad/desk accessory with a clear creator audience of digital artists and notetakers.", "opportunity_availability": "Creator community application is open now via Sprout Social, with a stated 5K+ follower threshold.", "ugc_evidence": "Dedicated creator community, creators featured on brand socials, and explicit paid collaborations (e.g. annual Back-to-School content) on the official page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Linsoul', 'https://www.linsoul.com', 'Hi-Fi audio platform founded in 2016 by the Crazy HiFi team, bringing Chinese HiFi makers to listeners worldwide and housing its own brands THIEAUDIO, Kiwi Ears, ZiiGaat and Tripowin, selling in-ear monitors, headphones and DAC/AMPs. Its Programs page lists Affiliate, Product Ambassador (receive upcoming products for review) and Loyal Community (test and review products) routes for creators.', 'China', 'published') returning id into bid;
