  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Linsoul Affiliate Program (UpPromote) plus Product Ambassador / Loyal Community review programs', 'https://af.uppromote.com/linsoul/register', 'https://www.linsoul.com/pages/programs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.linsoul.com/pages/affiliate-program', 'official_site', 'affiliate', 'Official affiliate page: performance-based commissions of 5%-18% per referred sale, a custom unique link, 14-day cookies and UpPromote tracking; new affiliates earn 5%, payments are processed around the 10th of each month with a USD $10 minimum payout, free to join with no minimum sales quota. No cap or earning-limit statement appears on the page, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://af.uppromote.com/linsoul/register', 'official_site', 'affiliate', 'UpPromote register page: commission type Percent Of Sale at 5%, with a tiered structure — Tier 1 $0-5,000 5%, Tier 2 $5,000-10,000 8%, Tier 3 $10,000-50,000 10%, Tier 4 $50,000-100,000 12%, Tier 5 $100,000-150,000 15%, Tier 6 $150,000+ 18% — evaluated quarterly.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.linsoul.com/pages/programs', 'official_site', 'ugc_collab', 'Programs page: Affiliate Program under ''Create & review'' (5%-18%, 14-day cookies), a Product Ambassador route (receive upcoming products for review and help manufacturers refine products) and a Loyal Community route (test and review products, sometimes before launch, with an original review and photos).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.linsoul.com/pages/about-linsoul', 'official_site', 'general', 'About page: Linsoul began with the Crazy HiFi team in 2016, built around audiophile communities, bringing Chinese HiFi makers closer to listeners worldwide; its own brands are THIEAUDIO, Kiwi Ears, ZiiGaat and Tripowin.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 17, 11, 10, 4, '{"compensation": "Fully published tiered 5%-18%, $10 minimum payout, monthly payment; no cap statement found, so the cap remains unknown.", "contact_access": "A live UpPromote application and a published PR email (joyce@linsoul.com); no direct affiliate email published on fetched pages.", "credibility": "Detailed official about, affiliate terms and parent-company pages; 2016 founding corroborated across official and press-release sources.", "niche_fit": "Niche audiophile audio accessories (IEMs, headphones, DAC/AMPs) at the smaller creator-friendly end, not a mass headphone giant.", "opportunity_availability": "Live register page plus multiple creator programs listed on the official Programs page.", "ugc_evidence": "Separate Product Ambassador and Loyal Community test-and-review programs alongside the affiliate program, with authentic-content guidance on the affiliate page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('JOURNEY', 'https://journeyofficial.com', 'JOURNEY is a consumer electronics and lifestyle accessories brand, described on its official site as an ALOGIC brand creating innovative consumer electronics, with products designed in Australia. Its range includes wireless charging desk mats and charging stations, plus LOC8 trackable wallets and tracker accessories that work with Apple Find My and Google Find Hub, sold through regional stores for the US, UK, Australia and worldwide.', 'Australia', 'published') returning id into bid;
