  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://journeyofficial.com/pages/affiliates-sign-up', 'official_site', 'affiliate', 'Official ''Journey Official Global Affiliate Program'' page: publishers earn 15% commission on each sale, average order value $100, 30-day cookie, monthly paychecks; sign-up routes to ShareASale. The page also states the products are designed in Australia.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://journeyofficial.com/blogs/press-releases/journey-s-leanest-ever-wallet-is-a-trackable-one-for-people-who-pay-by-phone', 'official_site', 'contact', 'Official press release (Melbourne, Australia dateline) describes JOURNEY as ''an ALOGIC brand'' in innovative consumer electronics, launches the LOC8 VERSA Slim trackable wallet, publishes pr@journeyofficial.com for media enquiries, and repeats: ''Publishers earn 15% on each sale, and our program is free to join.''', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 12, 18, 13, 7, 5, '{"compensation": "The highest verified tech rate in this group: 15% per sale on a stated $100 average order value, 30-day cookie, monthly pay.", "contact_access": "Published PR email pr@journeyofficial.com plus a public affiliate sign-up page.", "credibility": "Detailed terms (rate, AOV, cookie, payout cadence) published on the brand''s own affiliate page.", "niche_fit": "Core consumer tech: wireless charging desk accessories and trackable phone wallets/trackers.", "opportunity_availability": "The affiliate program is public and free to join, but no named, dated creator opportunity was found.", "ugc_evidence": "The program is framed for publishers/affiliates; no explicit creator/UGC campaign was found on fetched pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Camp Snap', 'https://www.campsnapphoto.com', 'Camp Snap makes reusable, screen-free digital cameras designed to help people stay present — no playback screen, point-and-shoot operation — originally created for children at summer camp and now also sold to adult nostalgia and travel audiences. Its official About page says it was founded by Brian and Melanie, former summer campers from Toronto now living in Hermosa Beach, California; Beacons lists it as an electronics brand based in Redondo Beach, US, with 1–50 employees.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
