  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Camp Snap Ambassador Program (Superfiliate) — personal link, commission on every sale, early access to drops, campaign/community features', 'https://campsnapcamera.superfiliate.com/portal/sign-up', 'https://www.campsnapphoto.com/pages/camp-snap-ambassadors', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.campsnapphoto.com/pages/camp-snap-ambassadors', 'official_site', 'affiliate', 'Official ambassador page: apply via Superfiliate for a personal link and commission on every sale, early access and campaign features; or via ShopMy — ''Add Camp Snap to your Shop and earn 10% commission on every sale'' — plus creator challenges and bonuses.', 'verified', now());
