  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.campsnapphoto.com/pages/about-us', 'official_site', 'general', 'Official About page: founded by Brian and Melanie after finding no screen-free digital cameras for kids; the cameras are designed to help children stay present and capture camp memories without screen time. The brand''s official contest page identifies @campsnapcamera as its official Instagram account.', 'verified', now());
