  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/cleobella', 'listing', 'ugc_collab', 'NewCollab states Cleobella does not publish an open creator programme, works with creators worldwide via a direct pitch to its team, looks for around 500+ followers with niche fit mattering more than the number, and mainly runs a gifting programme of free product with no fee, typical PR package about $120.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/cleobella/', 'listing', 'affiliate', 'Commission-cap check: the LinkClicky ShareASale listing and the NewCollab page contain no ''no cap'', ''unlimited earnings'' or earnings-limit FAQ statement, so commission_cap is unknown, not uncapped, despite the published 20% rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/cleobella', 'listing', 'ugc_collab', 'Creator-saturation check: NewCollab reports no open creator programme and no public UGC programme, but publishes no creator count, sponsored-post count or first-creator recruiting claim, so there is insufficient evidence for ''low'' and creator_saturation is unknown.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fastcompany.com/90974971/how-cleobella-scaled-from-an-la-farmers-market-stand-to-global-clothing-powerhouse', 'article', 'general', 'Fast Company reports Angela O''Brien founded Cleobella in 2006, grew it from a Los Angeles farmer''s market stall, and works with artisans in Bali and elsewhere, corroborating brand credibility and origin.', 'publicly_reported', now());
