  insert into public.brands (name, website, description, country, status) values ('Girlfriend Collective', 'https://girlfriend.com', 'Girlfriend Collective is a Seattle-based sustainable activewear brand creating stylish workout clothes from recycled materials like water bottles and fishing nets, and is size-inclusive and ethically made. Its range spans XXS to 6XL, and it works with creators through PR gifting as well as an affiliate program listed at 10% per sale.', 'US', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', null, 'https://newcollab.co/brand/girlfriend-collective', 'https://newcollab.co/brand/girlfriend-collective', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/girlfriend-collective/.', 'https://getlasso.co/affiliate/girlfriend-collective/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Girlfriend Collective Affiliate Program / PR & Influencer Gifting Program', 'https://getlasso.co/affiliate/girlfriend-collective/', 'https://newcollab.co/brand/girlfriend-collective', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/girlfriend-collective/', 'listing', 'affiliate', 'Lasso listing: Girlfriend Collective affiliate program commission rate 10% per sale, 30-day cookie, in the Fashion category. CompareEPC''s activewear table also lists Girlfriend Collective on Impact at 10%.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/activewear-affiliate-programs/', 'listing', 'affiliate', 'CompareEPC activewear affiliate table lists Girlfriend Collective with network ''impact'' and a 10% rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/girlfriend-collective', 'listing', 'ugc_collab', 'NewCollab PR & Influencer Gifting Program page: Girlfriend Collective works with creators through its PR team via a short email pitch, looks for around 500 followers or more with niche fit mattering more, works with creators worldwide, mainly runs a gifting programme with no fee, and states ''We haven''t found a public UGC program, open brief or creator ads''; it also notes @girlfriend has 44K followers on TikTok across 18 posts. No PR email address is published in the fetched text, so none is recorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/girlfriend-collective/', 'listing', 'affiliate', 'Commission-cap check: the Lasso and CompareEPC listings publish a 10% rate with no statement of ''no cap'', ''unlimited earnings'', or an earnings-limit FAQ/term, so commission_cap is unknown, not uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newcollab.co/brand/girlfriend-collective', 'listing', 'general', 'Creator-saturation check: NewCollab gives no creator count for Girlfriend Collective and reports no public UGC program was found, and no Beacons/CollabFeed creator count was found in the fetched sources, so creator_saturation is unknown rather than low or high.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 12, 5, 7, 5, '{"compensation": "Published 10% per sale on Impact listings; cap unknown with no uncapped statement, and PR gifting itself is no-fee.", "contact_access": "PR pitch route is described on NewCollab, but no email or direct contact was published on the fetched pages, so contacts carry no email.", "credibility": "Established Seattle brand; two listings agree on 10% and a podcast transcript confirms a dedicated affiliate/influencer marketing role at the brand.", "niche_fit": "Size-inclusive sustainable activewear in XXS-6XL is a strong fitness fit.", "opportunity_availability": "Affiliate program is listed as joinable and the PR route is open to creators with around 500+ followers worldwide.", "ugc_evidence": "NewCollab verifies PR/influencer gifting for creators, but explicitly found no public UGC program or open brief."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Unbound Merino', 'https://unboundmerino.com', 'Unbound Merino was created by three friends looking to pack light and own less, according to its official affiliate page. A network listing describes it as crafting high-quality, versatile merino wool clothing designed for the modern traveler seeking style and functionality. Its program works with media publishers, bloggers, review sites and creators across YouTube, Instagram, TikTok and Facebook.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'unboundmerinoinfluencer@accelerationpartners.com', 'https://unboundmerino.com/pages/affiliate-program', 'https://unboundmerino.com/pages/affiliate-program', 'verified', now());
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'unboundmerino@accelerationpartners.com', 'https://unboundmerino.com/pages/affiliate-program', 'https://unboundmerino.com/pages/affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://unboundmerino.com/pages/affiliate-program.', 'https://unboundmerino.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Unbound Merino Affiliate Program (via Impact)', 'https://unboundmerino.com/pages/affiliate-program', 'https://unboundmerino.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://unboundmerino.com/pages/affiliate-program', 'official_site', 'affiliate', 'Official affiliate page states: ''The program offers a 10-12% baseline commission on all orders through your links, with a 30-day cookie window.'' It says applicants must first become a member of the Impact network, its third-party program administrator, and should receive a confirmation within 24 to 48 hours. Commission rate is recorded as 10, the low end of the published 10-12% baseline range.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://unboundmerino.com/pages/affiliate-program', 'official_site', 'affiliate', 'Commission-cap check: the fetched official affiliate page contains no ''no cap'', ''unlimited earnings'', earnings-limit FAQ or program-terms statement about a commission cap. A published percentage alone is not an uncapped statement, so commission_cap is ''unknown'', not ''uncapped''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://unboundmerino.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'Creator-saturation check: no creator count, sponsored-post count or Beacons/CollabFeed/NewCollab figure was found on the fetched official page or listings, so creator_saturation is ''unknown'', not ''low''. The same page does evidence creator work: ''We typically work with creators on a CPA (Cost Per Acquisition) basis and we''re also willing to offer samples depending on the opportunity.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://unboundmerino.com/pages/affiliate-program', 'official_site', 'contact', 'Two emails are published on the official page: unboundmerino@accelerationpartners.com for affiliate-program help if no confirmation email arrives, and unboundmerinoinfluencer@accelerationpartners.com for discussing influencer/creator partnerships outside the affiliate program.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 12, 15, 9, 5, '{"compensation": "Published 10-12% baseline on the official page, but no published cap statement, so no uncapped credit.", "contact_access": "Two published emails, including a dedicated influencer partnerships address.", "credibility": "Established DTC travel-apparel brand with a detailed official program FAQ.", "niche_fit": "Merino travel clothing built for packing light; squarely travel-clothing for the directory.", "opportunity_availability": "Joinable now via Impact from the official page, with confirmation stated at 24-48 hours.", "ugc_evidence": "Official page explicitly works with YouTube/Instagram/TikTok/Facebook creators on CPA and offers samples depending on opportunity."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Pacsafe', 'https://pacsafe.com', 'Pacsafe''s own partner page describes it as a global anti-theft bag brand trusted in 90+ countries since 1998. A travel affiliate review summarises it as a well-known travel gear brand specialising in anti-theft backpacks, bags and accessories designed to help travellers protect their valuables on the go. Its official affiliate page targets sustainable and solo travellers and offers collaboration opportunities.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program.', 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pacsafe Affiliate Program (via AvantLink)', 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'official_site', 'affiliate', 'Official affiliate page states: ''Join the Pacsafe family with our premium affiliate program, offering an 8% commission on sales'' and ''Being a Pacsafe affiliate, you will earn a 8% commission, get 60 day cookie tracking and have the opportunity to collaborate with us.'' Its Join Our Program / More Info links point to avantlink.com, evidencing AvantLink as the network route.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'official_site', 'affiliate', 'Commission-cap check: the fetched official affiliate page contains no ''no cap'', ''unlimited earnings'', earnings-limit FAQ or terms statement about a commission cap. A published 8% rate alone is not an uncapped statement, so commission_cap is ''unknown'', not ''uncapped''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pacsafe.com/en-ca/pages/pacsafe-affiliate-program', 'official_site', 'ugc_collab', 'Creator-saturation check: no creator count, sponsored-post count or Beacons/CollabFeed/NewCollab figure was found on the fetched official page or listings, so creator_saturation is ''unknown'', not ''low''. Creator relevance is evidenced by the page''s invitation to sustainable/solo travellers and its stated opportunity to collaborate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.pacsafe.marketing/', 'official_site', 'general', 'Pacsafe''s partner page describes Pacsafe as ''a global anti-theft bag brand, trusted in 90+ countries since 1998'', supporting the brand description and credibility. That page is an agency performance-partner offer, not the creator affiliate route, so it was not used for the affiliate rate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 10, 6, 9, 5, '{"compensation": "Published 8% with a 60-day cookie on the official page, but no published cap statement.", "contact_access": "No published email on the fetched page; access is via the AvantLink join links only.", "credibility": "Brand states it has been trusted in 90+ countries since 1998.", "niche_fit": "Anti-theft travel backpacks and bags are a core travel-gear fit.", "opportunity_availability": "Joinable now through the Join Our Program links on the official page.", "ugc_evidence": "Official page invites travellers to join and collaborate, but gives less creator-specific detail than Unbound Merino."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tortuga Backpacks', 'https://www.tortugabackpacks.com', 'A travel brands directory describes Tortuga as making carry-on travel backpacks, daypacks and travel accessories for city travel. A travel-accessories affiliate listing adds that Tortuga is best known for its travel backpacks and also sells small daily backpacks, travel cubes and waterproof covers for backpacks. Its affiliate program is reported to run through AvantLink, with separate options for website publishers and social media influencers.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.avantlink.com/signup/affiliate', 'https://onemorecupof-coffee.com/best-travel-accessories-affiliate-programs/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://onemorecupof-coffee.com/best-travel-accessories-affiliate-programs/.', 'https://www.avantlink.com/signup/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tortuga Affiliate Program via AvantLink (publisher and influencer options)', 'https://www.avantlink.com/signup/affiliate', 'https://onemorecupof-coffee.com/best-travel-accessories-affiliate-programs/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://onemorecupof-coffee.com/best-travel-accessories-affiliate-programs/', 'listing', 'affiliate', 'Listing states for Tortuga: Commission 10%, Cookie 60 days, ''The affiliate program is run through AvantLink, and there are separate options for website publishers and social media influencers'' and ''High-performing affiliates can get sample products to review.'' The same 10% / 60-day / AvantLink terms are corroborated by a second fetched listing at runtheaffiliatemarket.com and by carlbroadbent.com. No official Tortuga affiliate page was located in search, so this rate is listing-sourced, not official-site verified.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://onemorecupof-coffee.com/best-travel-accessories-affiliate-programs/', 'listing', 'affiliate', 'Commission-cap check: none of the fetched Tortuga listings contains a ''no cap'', ''unlimited earnings'', earnings-limit FAQ or program-terms statement about a commission cap. A published 10% rate alone is not an uncapped statement, so commission_cap is ''unknown'', not ''uncapped''.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fairing.co/customers/tortuga-backpacks', 'article', 'ugc_collab', 'Creator-saturation check: no creator count, sponsored-post count or Beacons/CollabFeed/NewCollab figure was found, so creator_saturation is ''unknown'', not ''low''. The fetched Fairing case study does show a mature affiliate/influencer channel — it reports affiliate or influencer referrals drove 49% of Tortuga''s business per customer responses and that Tortuga formalised seeding 15-20 sample packages per launch — which is why saturation is not claimed as low.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bravodm.com/brands/category/travel', 'listing', 'general', 'BravoDM''s travel brands directory, checked October 2026, lists Tortuga as ''Carry-on travel backpacks, daypacks and travel accessories for city travel'' and lists it among travel brands with creator programs, supporting niche fit and that a creator route exists.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 13, 11, 5, 8, 4, '{"compensation": "10% with a 60-day cookie reported consistently across multiple listings, but not on an official Tortuga page and with no published cap statement.", "contact_access": "No published email found; access is only via the AvantLink affiliate application.", "credibility": "Long-running travel backpack brand, but program terms here rest on listings rather than an official program page.", "niche_fit": "Carry-on travel backpacks and travel accessories are a direct travel-gear fit.", "opportunity_availability": "Joinable via AvantLink, though one listing reports traffic/authority thresholds favouring larger publishers, so availability is not fully open.", "ugc_evidence": "Listings report a separate social-media-influencer option and sample products for high-performing affiliates; Fairing documents an active influencer seeding process."}'::jsonb);
